// Error Trigger gives either {execution, workflow} or, when the trigger node itself failed, {trigger, workflow}
const d = $input.first().json;
const wf = d.workflow?.name || 'Unknown workflow';
const ex = d.execution || {};
const err = ex.error || d.trigger?.error || {};
const node = ex.lastNodeExecuted || err.node?.name || 'trigger';
const msg = String(err.message || 'No error message').replace(/\s*\[line \d+\]$/, '').slice(0, 300);
const time = $now.setZone('Asia/Dhaka').toFormat('dd LLL yyyy, h:mm a');
const lines = [
  '\u26a0\ufe0f Noorzaah automation failed',
  '',
  `Workflow: ${wf}`,
  `Failed at: ${node}`,
  `Error: ${msg}`,
  `Time: ${time}`,
];
if (ex.id) lines.push(`Execution: #${ex.id}`);
if (ex.url) lines.push(ex.url);
return [{ json: { text: lines.join('\n') } }];
